#!/usr/bin/env python3
"""Integrate the audited explicit ordinary cubic class character."""
from pathlib import Path
import datetime
import json
import subprocess

w = Path(__file__).resolve().parents[1]
stamp = datetime.datetime.now(datetime.timezone.utc).strftime('%H:%M UTC')
record = {
    'answers': 'A5; A9; A15; L10; L14; L20',
    'depends_on': 'A.138 constant sextic field three-class vanishing; A.155 exact balanced quotient and norm maps; A.165 literal principal quadratic changed primes; A.168 nonzero ordinary two-prime class; exact Kummer and class-field maps proved in the section',
    'uses_local_theorem': 'no',
    'manuscript_passages': 'cote149; scans56–58 and126–127; exact norm obstruction and ordinary-to-balanced character map',
    'notes': 'The literal radical (1+6*zeta*alpha)/(1+6*zeta^2*alpha), with alpha^3=3, gives compatible nontrivial unramified cyclic cubic extensions of K_n, n>=2, splitting every prime over2 and3. Their ordinary class characters have changed-prime values(2,0,1,0), with the residue-degree-two Frobenius restriction explicitly retained. They kill the nonzero ordinary two-prime class of A168 and have balanced-relation values(2,1), so they do not descend to C_n^bal. Consequently the three-primary ordinary class group, and its subgroup generated by S-prime classes, have order at least9 for n>=3. The complete anti-invariant F-S-unit radical source modulo cubes is proved to have basis zeta, epsilon, u2, u11, u59 using an explicit norm-four unit and prime-to3 saturation. Its everywhere unramified pullback at every higher level is exactly the single product line. This finite source classification does not assert exhaustion of all class characters or settle e3.'
}
p = w / 'SECTIONS_OVER_Q_paper.tex'
s = p.read_text()
anchor = r'\input{sections/harmonic_full_metabelian_classification.tex}'
new = r'\input{sections/two_inert_genus_character.tex}'
assert anchor in s
if new not in s:
    s = s.replace(anchor, anchor + '\n' + new, 1)
p.write_text(s)
p = w / 'notes/register_metadata.json'
meta = json.loads(p.read_text()); meta['A.170'] = record
p.write_text(json.dumps(meta, indent=2, ensure_ascii=False) + '\n')
detail = 'A.170 constructs the exact unramified cubic ordinary class character, proves its balanced-relation values(2,1), and exhausts the specified anti-invariant base-field S-unit source. It proves ordinary three-class-group size at least9 from level3; e3 remains undecided.'
p = w / 'SECTIONS_OVER_Q_report.md'; lines = p.read_text().splitlines()
assert lines[0] == 'INCOMPLETE'
answers = {x.strip() for x in record['answers'].split(';')}
for i, line in enumerate(lines[:55]):
    if not line.startswith('| '): continue
    cells = [x.strip() for x in line.strip().strip('|').split('|')]
    if len(cells) == 3 and cells[0] in answers:
        if 'A.170' not in cells[1]: cells[1] += ', A.170'
        if detail not in cells[2]: cells[2] += ' ' + detail
        lines[i] = '| ' + ' | '.join(cells) + ' |'
heading = '## Continued work: an exact ordinary class character and its balanced restriction'
if heading not in lines:
    lines.extend(['', heading, '', stamp + ': ' + detail, '',
        'The cyclic cubic field is given by its radical, the actual involution extending complex conjugation, and a literal cubic trace polynomial with square discriminant. The explicit global unit in the sextic base has relative norm alpha^2-2 and supplies the missing anti-invariant unit generator modulo cubes. Its local depth1, the depth5 changed-prime radicals, and a depth7 representative of the cyclotomic unit give an exhaustive three-adic test on that finite source. The actual root-stabilizer normal-closure map proves that the same test controls unramified pullback at all heights. The global radical remains nontrivial, the class character is onto, and its two-prime value is zero. Its nonzero values on the precisely defined balanced relations prove its failure to descend. The ordinary class-size bound follows from the nonzero kernel element proved in A168, without asserting a rank-two subgroup.', '',
        'All three complete-source audits and both independent exact algebraic certificates passed. A local/global notation ambiguity was corrected before integration: cubes in the three-adic completion are explicitly distinguished by the actual completion map from global radical classes. No class-group computation or balanced vanishing result is inferred from the finite certificates.', ''])
p.write_text('\n'.join(lines) + '\n')
audit = stamp + ' A170 integrated after complete root/local/birational proof audits, correction of the completion notation, and independent exact certificate reruns. The five-dimensional source, unique unramified line, ordinary class maps, Frobenius values and balanced nonfactorization all passed.\n'
for name in ['notes/hour13_root_audits.md', 'notes/root_progress.md']:
    with (w / name).open('a') as f: f.write('\n' + audit)
proc = subprocess.run(['python', str(w / 'code/build_register.py')], capture_output=True, text=True, check=True)
out = 'Integrated audited A170.\n' + proc.stdout
Path(__file__).with_name('integrate_a170_output.txt').write_text(out)
print(out, end='')
